import { test, expect } from '@playwright/test';

test.describe('Async PDF Generation Download', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/pdf-generator');
  });

  test('should generate and download PDF when async generation completes', async ({ page }) => {
    // Intercept the PDF generation API call
    await page.route('**/api/generate-pdf', (route) => {
      route.abort('blockedbyclient');
    });

    // Set up the download listener
    await page.on('download', async (download) => {
      const path = await download.path();
      expect(path).toContain('pdf-document');
      await expect(download).toBeFinished();
    });

    // Set up the API response with delay
    await page.route('**/api/generate-pdf', (route) => {
      setTimeout(() => {
        route.fulfill({
          status: 200,
          contentType: 'application/pdf',
          body: Buffer.from([0x25, 0x04, 00, 00, 00, 00, 00, 00, 00, 00, 00, 00, 00, 00, 00, 00]),
        });
      }, 2000);
    });

    // Click the generate button using getByRole
    const generateButton = page.getByRole('button', { name: /generate pdf/i });
    await expect(generateButton).toBeVisible();
    await generateButton.click();

    // Verify loading state appears
    const loadingIndicator = page.getByText(/generating/i);
    await expect(loadingIndicator).toBeVisible();

    // Wait for the API response and download to complete
    await page.waitForTimeout(2500);

    // Verify loading state disappears
    await expect(loadingIndicator).not.toBeVisible();

    // Verify success message appears
    const successMessage = page.getByText(/pdf generated successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify download link is visible
    const downloadLink = page.getByRole('link', { name: /download pdf/i });
    await expect(downloadLink).toBeVisible();

    // Click the download link using getByRole
    await downloadLink.click();

    // Verify download confirmation
    const downloadConfirmation = page.getByText(/download started/i);
    await expect(downloadConfirmation).toBeVisible();
  });

  test('should handle PDF generation failure and display error message', async ({ page }) => {
    // Intercept the PDF generation API call and return an error
    await page.route('**/api/generate-pdf', (route) => {
      route.fulfill({
        status: 500,
        contentType: 'application/json',
        body: JSON.stringify({ error: 'Server error during PDF generation' }),
      });
    });

    // Click the generate button using getByRole
    const generateButton = page.getByRole('button', { name: /generate pdf/i });
    await expect(generateButton).toBeVisible();
    await generateButton.click();

    // Verify loading state appears
    const loadingIndicator = page.getByText(/generating/i);
    await expect(loadingIndicator).toBeVisible();

    // Wait for the API response
    await page.waitForTimeout(1000);

    // Verify loading state disappears
    await expect(loadingIndicator).not.toBeVisible();

    // Verify error message appears
    const errorMessage = page.getByText(/error generating pdf/i);
    await expect(errorMessage).toBeVisible();

    // Verify error details are displayed
    const errorDetails = page.getByText(/server error/i);
    await expect(errorDetails).toBeVisible();

    // Verify download link does not appear
    const downloadLink = page.getByRole('link', { name: /download pdf/i });
    await expect(downloadLink).not.toBeVisible();
  });
});
